const assert = require('node:assert/strict');
const fs = require('node:fs');
const vm = require('node:vm');
const path = require('node:path');
const alerts = [], requests = [];
const elements = new Map();
const element = id => { if (!elements.has(id)) elements.set(id, {innerHTML:'',textContent:'',value:'',classList:{add(){},remove(){}}}); return elements.get(id); };
const ctx = {console, document:{readyState:'loading',addEventListener(){},getElementById:element,querySelectorAll(){return [{dataset:{index:'0'}},{dataset:{index:'1'}}]}}, confirm:()=>true,alert:message=>alerts.push(message)};
vm.createContext(ctx);
vm.runInContext(fs.readFileSync(path.join(__dirname,'../app.js'),'utf8'),ctx);
const realLoadCleanablePods = ctx.loadCleanablePods;
vm.runInContext(`loadCleanablePods=async()=>{}; loadStatus=async()=>{};`,ctx);
async function main(){
 vm.runInContext(`cleanablePods=[{namespace:'a',name:'worker'},{namespace:'b',name:'worker'}]`,ctx);
 ctx.apiFetch = async (_url, options) => {const body=JSON.parse(options.body);requests.push(body);return {ok:true,status:202,json:async()=>({proposals:[{id:'p-'+body.namespace,status:'PENDING_APPROVAL'}]})};};
 await ctx.cleanSelectedPods(false);
 assert.equal(requests.length,2,'cleanup must preserve separate namespace targets');
 assert.deepEqual(requests.map(r=>r.namespace).sort(),['a','b']);
 assert.ok(alerts.some(s=>/pending approval/i.test(s)),'show proposals pending approval');
 assert.ok(alerts.every(s=>!/undefined|cleaned .*success/i.test(s)),'do not claim deletion');
 ctx.apiFetch=async()=>({ok:true,status:202,json:async()=>({proposals:[{id:'reused',status:'EXECUTING'}]})});
 await ctx.cleanSinglePod('a','worker');
 assert.match(alerts.at(-1),/1 already approved or executing/);
 assert.doesNotMatch(alerts.at(-1),/1 cleanup proposals pending approval/);
 const proposal={id:'p1',namespace:'a',name:'worker',kind:'Pod',status:'EXECUTING',diagnosis:{severity:'HIGH',provider_name:'rule',summary:'check',root_cause:'unknown',action_type:'RestartPod',confidence_score:0.5,proposed_command:'restart'}};
 ctx.apiFetch=async()=>({ok:true,json:async()=>[proposal]});
 await ctx.loadProposals();
 assert.match(element('proposals-container').innerHTML,/EXECUTING/,'execution remains visible');
 assert.doesNotMatch(element('proposals-container').innerHTML,/data-action="approve-proposal"/,'executing actions cannot be approved again');
 ctx.apiFetch=async()=>({ok:true,json:async()=>[]});
 await ctx.loadProposals();
 assert.doesNotMatch(element('proposals-container').innerHTML,/all clear|telemetry is stable/i);
 ctx.apiFetch=async()=>({ok:false,status:503,json:async()=>({error:'unavailable'})});
 await ctx.loadProposals();
 assert.match(element('proposals-container').innerHTML,/unavailable|could not|stale/i,'surface failed refresh');
 proposal.status='REJECTED'; proposal.rejection_reason='<unsafe> reason';
 ctx.apiFetch=async()=>({ok:true,json:async()=>[proposal]});
 await ctx.loadProposals();
 assert.match(element('proposals-container').innerHTML,/&lt;unsafe&gt; reason/);
 assert.doesNotMatch(element('proposals-container').innerHTML,/Awaiting execution result/);
 proposal.status='COMPLETED'; proposal.rejection_reason=''; proposal.verification_error='check timed out';
 await ctx.loadProposals();
 assert.match(element('proposals-container').innerHTML,/check timed out/);
 ctx.apiFetch=async()=>({ok:true,json:async()=>[{namespace:'a',name:'worker'}]});
 await realLoadCleanablePods();
 assert.match(element('cleanable-pods-tbody').innerHTML,/data-action="clean-pod"/);
 ctx.apiFetch=async()=>({ok:false,status:503,json:async()=>({error:'unavailable'})});
 await realLoadCleanablePods();
 assert.match(element('cleanable-pods-tbody').innerHTML,/unavailable|stale/i);
 assert.doesNotMatch(element('cleanable-pods-tbody').innerHTML,/data-action="clean-pod"/);
 assert.equal(vm.runInContext('cleanablePods.length',ctx),0);
 console.log('proposal workflow contracts passed');
}
main().catch(err=>{console.error(err);process.exitCode=1;});
